/*
 * Regenerates browser/icon.png from the embedded base64 PNG.
 * Custom stylized Discord logo (blurple gradient + white Discord mark).
 * SPDX-License-Identifier: GPL-3.0-or-later
 */

import { writeFileSync } from "node:fs";

// 128x128 RGBA PNG
const ICON_BASE64 = "";

writeFileSync("browser/icon.png", Buffer.from(ICON_BASE64, "base64"));
console.log("browser/icon.png regenerated");
